		if(is_string($mutation['service'])&&self::serviceName($mutation['service'])!==$mutation['service']){throw new \InvalidArgumentException('Invalid Panel platform checkpoint.');}
		$expectedNested=[];foreach($checkpoint['services']as$name=>$service){if($service instanceof PanelCheckpointableService){$expectedNested[]=$name;}}$actualNested=array_keys($checkpoint['nested']);sort($expectedNested,SORT_STRING);sort($actualNested,SORT_STRING);if($expectedNested!==$actualNested){throw new \InvalidArgumentException('Invalid nested Panel platform checkpoint.');}
