			if(!is_array($nested)||array_keys($nested)!==['type','class','checkpoint']||!is_string($nested['type']??null)||!is_string($nested['class']??null)||!is_array($nested['checkpoint']??null)||!$service instanceof PanelCheckpointableService||$service::class!==$nested['class']||$service->checkpointType()!==$nested['type']){throw new \InvalidArgumentException('Invalid nested Panel platform checkpoint.');}
