	/**
	 * Builds opt-in first-party pages backed by this exact platform instance.
	 *
	 * Read requests render domain pages. Non-read requests are delegated to the
	 * existing controller mutation methods, retaining their method, CSRF,
	 * authorization, tenant, and audit boundaries.
	 *
	 * @param array<string,mixed> $options Page naming, navigation, and domain options.
	 * @return array<string,PanelPage>
	 */
	public function pages(array $options=[]):array{
		$manifest=$this->manifest();
		if(!$manifest->ready('platform')){throw new \LogicException('Panel platform pages require a ready platform controller and template.');}
		$prefix=Resource::normalizeName((string)($options['prefix']??'platform'))?:'platform';
		$group=trim((string)($options['group']??'Platform'))?:'Platform';
		$hidden=($options['hidden']??false)===true;
		$allowed=array_values(array_filter(array_map(static fn(mixed $domain):string=>Resource::normalizeName((string)$domain),is_array($options['domains']??null)?$options['domains']:[])));
		$catalogue=[
			'operations_os'=>['label'=>'Operations OS','description'=>'Work, commands, policy, domains, compliance, fleet, and releases in one governed console.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{return self::readRequest($request)?$this->operationsOsPage($domainOptions,$request):$this->controller()->operateOperationsOs($this->operationsConsole(),$request,$domainOptions);}],
			'operations'=>['label'=>'Operations','description'=>'Durable jobs, queues, progress, retries, and control.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{return self::readRequest($request)?$this->operationsPage($domainOptions,$request):$this->controller()->operate($this->operationControl(),$request,$domainOptions);}],
			'workflows'=>['label'=>'Workflows','description'=>'Definitions, transitions, approvals, assignments, and audit history.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{return self::readRequest($request)?$this->workflowsPage(isset($domainOptions['definition'])?(string)$domainOptions['definition']:null,$domainOptions,$request):$this->controller()->workflow($this->workflowEngine(),$request,$domainOptions);}],
			'automation'=>['label'=>'Automation','description'=>'Registered actions, execution plans, receipts, and rollback.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{if(self::readRequest($request)){return$this->automationPage(isset($domainOptions['action'])?(string)$domainOptions['action']:null,$domainOptions,$request);}$action=trim((string)$request->input('action',$domainOptions['action']??''));return$action!==''?$this->controller()->automate($this->automationExecutor(),$action,$request,$domainOptions):PanelPageResult::json(['ok'=>false,'status'=>'invalid','errors'=>['An automation action is required.']],422);}],
			'notifications'=>['label'=>'Notifications','description'=>'Inbox state, delivery, mentions, assignments, and activity.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{$recipient=self::pageUserId($request,$domainOptions);if($recipient===null){return self::missingUser();}$domainOptions['recipient']=$recipient;if(self::readRequest($request)){return$this->notificationsPage($domainOptions,$request);}$id=trim((string)$request->input('id',''));$notification=$id!==''?$this->notificationAdapter()->get($id):null;if($notification instanceof PanelInboxNotification&&$notification->recipient()!==null&&$notification->recipient()!==$recipient){return PanelPageResult::json(['ok'=>false,'status'=>'not_found'],404);}return$this->controller()->notify($this->notificationInbox(),$request,$domainOptions);}],
			'media'=>['label'=>'Media','description'=>'Uploads, processing, variants, delivery, and cleanup.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{return self::readRequest($request)?$this->mediaPage($domainOptions,$request):PanelPageResult::json(['ok'=>false,'status'=>'method_not_allowed'],405,['Allow'=>'GET, HEAD']);}],
			'preferences'=>['label'=>'Preferences','description'=>'Appearance, saved views, recents, pins, and device overrides.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{$userId=self::pageUserId($request,$domainOptions);if($userId===null){return self::missingUser();}$profile=(string)($domainOptions['profile']??'default');$device=isset($domainOptions['device'])?(string)$domainOptions['device']:null;$workspace=$this->preferences($userId,$profile,$device);return self::readRequest($request)?$this->controller()->preferences($workspace,$domainOptions,$request):$this->controller()->prefer($workspace,$request,$domainOptions);}],
			'collaboration'=>['label'=>'Collaboration','description'=>'Threads, comments, assignments, watchers, and presence.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{return self::readRequest($request)?$this->collaborationPage($domainOptions,$request):$this->controller()->collaborate($this->collaboration(),$request,$domainOptions);}],
			'packages'=>['label'=>'Packages','description'=>'Signed package discovery, publisher trust, availability, and version history.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{return self::readRequest($request)?$this->packagesPage($domainOptions,$request):PanelPageResult::json(['ok'=>false,'status'=>'method_not_allowed'],405,['Allow'=>'GET, HEAD']);}],
			'authentication'=>['label'=>'Authentication','description'=>'MFA, step-up challenges, trusted devices, and sessions.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{$userId=self::pageUserId($request,$domainOptions);if($userId===null){return self::missingUser();}return self::readRequest($request)?$this->authenticationPage($userId,$domainOptions,$request):$this->controller()->authenticate($this->authentication(),$request,$domainOptions);}],
			'security'=>['label'=>'Security','description'=>'Policy decisions, permission simulation, impersonation, and audit.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{return self::readRequest($request)?$this->securityPage(is_array($domainOptions['reports']??null)?$domainOptions['reports']:[],$domainOptions,$request):PanelPageResult::json(['ok'=>false,'status'=>'method_not_allowed'],405,['Allow'=>'GET, HEAD']);}],
			'development'=>['label'=>'Developer','description'=>'Manifest inspection, diffs, schema blueprints, and quality plans.','render'=>function(PanelRequest $request,array $domainOptions):PanelPageResult{return self::readRequest($request)?$this->developerPage($domainOptions['manifest']??$this->manifest(),$domainOptions,$request):PanelPageResult::json(['ok'=>false,'status'=>'method_not_allowed'],405,['Allow'=>'GET, HEAD']);}],
		];
		$pages=[];$sort=(int)($options['sort']??800);
		foreach($catalogue as$domain=>$definition){
			if(($allowed!==[]&&!in_array($domain,$allowed,true))||!$manifest->ready($domain)){continue;}
