	/** @param array<string,mixed> $config @return array<string,mixed>|false */ private static function domain(array $config,string $name):array|false{$value=$config[$name]??[];if($value===false){return false;}if($value===true||$value===null){return[];}if(!is_array($value)){throw new \InvalidArgumentException("Panel platform domain '{$name}' configuration must be an array, true, or false.");}return$value;}
