	/** @param array<string,mixed> $options */ private static function pageUserId(PanelRequest $request,array $options):?string{$resolved=$options['user_id']??null;if(is_callable($resolved)){try{$resolved=$resolved($request);}catch(\Throwable){return null;}}if($resolved===null){$resolved=$request->user();}if(is_scalar($resolved)){$resolved=trim((string)$resolved);return$resolved!==''?$resolved:null;}if(is_array($resolved)){foreach(['id','user_id','key']as$key){if(isset($resolved[$key])&&is_scalar($resolved[$key])&&trim((string)$resolved[$key])!==''){return(string)$resolved[$key];}}}if(is_object($resolved)){foreach(['id','user_id','key']as$key){if(isset($resolved->{$key})&&is_scalar($resolved->{$key})&&trim((string)$resolved->{$key})!==''){return(string)$resolved->{$key};}}foreach(['getId','id','key']as$method){if(method_exists($resolved,$method)){try{$value=$resolved->{$method}();if(is_scalar($value)&&trim((string)$value)!==''){return(string)$value;}}catch(\Throwable){return null;}}}}return null;}
	private static function missingUser():PanelPageResult{return PanelPageResult::json(['ok'=>false,'status'=>'unauthenticated','errors'=>['An authenticated user is required.']],401);}
